function extractAtlas(image){
 const raw=document.createElement('canvas');raw.width=image.naturalWidth;raw.height=image.naturalHeight;const c=raw.getContext('2d',{willReadFrequently:true});c.drawImage(image,0,0);const w=raw.width,h=raw.height,data=c.getImageData(0,0,w,h).data,ids=new Int32Array(w*h),queue=new Int32Array(w*h),parts=[];let tag=0;
 for(let start=0;start<w*h;start++){if(ids[start]||data[start*4+3]<90)continue;tag++;let head=0,tail=1;queue[0]=start;ids[start]=tag;let x0=w,y0=h,x1=0,y1=0;while(head<tail){let n=queue[head++],x=n%w,y=(n/w)|0;x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);const visit=z=>{if(!ids[z]&&data[z*4+3]>=90){ids[z]=tag;queue[tail++]=z}};if(x>0)visit(n-1);if(x<w-1)visit(n+1);if(y>0)visit(n-w);if(y<h-1)visit(n+w)}if(tail>300)parts.push({tag,count:tail,x:x0,y:y0,w:x1-x0+1,h:y1-y0+1})}
 const biggest=parts.sort((a,b)=>b.count-a.count).slice(0,10);if(biggest.length!==10)throw Error('El atlas no contiene diez siluetas');biggest.sort((a,b)=>(a.y+a.h/2)-(b.y+b.h/2));const ordered=[...biggest.slice(0,5).sort((a,b)=>a.x-b.x),...biggest.slice(5).sort((a,b)=>a.x-b.x)];return ordered.map(a=>{let tile=document.createElement('canvas');tile.width=a.w;tile.height=a.h;let tc=tile.getContext('2d'),pixels=tc.createImageData(a.w,a.h);for(let y=0;y<a.h;y++)for(let x=0;x<a.w;x++){let n=(a.y+y)*w+a.x+x;if(ids[n]!==a.tag)continue;let k=(y*a.w+x)*4;for(let j=0;j<4;j++)pixels.data[k+j]=data[n*4+j]}tc.putImageData(pixels,0,0);return{image:tile,x:0,y:0,w:a.w,h:a.h}})
}
function loadAttackFrames(url,pose){let image=new Image();image.onload=()=>{try{attackFrames[pose]=extractAtlas(image)}catch(e){console.warn('No se pudo cargar una pose',e)}};image.src=url}

